; C64 Math Library: optional sum_fast ATAN2 kernel, WITH all required tables.
; GENERATED by routines/atan2/export_optimized.py; edit the canonical source.
; Assemble: acme -f cbm -o atan2.prg atan2_s8_s8_u8_sum_fast.asm
; Load the PRG, bank RAM in as necessary, and JSR atan2_s8_s8_u8.
; X0/Y0/Z0 are memory addresses, not CPU registers. Set D=0 before calling.
; No initialization, ZP, scratch, self-modifying code, or extra stack is needed.
; The only stack use is the caller's ordinary two-byte JSR return address.
; To relocate, edit ATAN2_CODE, PUBLIC_ENTRY, X0/Y0/Z0 and the table constants.
; Keep tables page aligned and all code/data/I/O/stack regions disjoint.
; Use page-aligned ATAN2_CODE for the published cycle counts.
; This standalone layout is NOT an overlay for the shipped resident profiles.
!cpu 6502
ATAN2_CODE = $8000
PUBLIC_ENTRY = $7F00
* = PUBLIC_ENTRY
atan2_s8_s8_u8:
    jmp atan2

; Four-page ATAN2: two biased log pages and two reflected angle pages.
; Inputs X0/Y0 are preserved; Z0 and A return phase; D=0 required, C=0 returned.
; Same outputs as the original compact/fast kernels. No ZP or self-modification.
; For nonzero x, LOGX=q(abs(x)); LOGY=82-q(abs(y)), or 174 for y=0.
; CLC/ADC therefore produces an index <=255 and *clears carry on every path*.
; The negative-x paths use an XOR half-turn instead of two additional pages.
X0=$C000
Y0=$C004
Z0=$C008
LOGX=$9400
LOGY=$9500
QPOS=$9600
QNEG=$9700
* = ATAN2_CODE
atan2:
    ldx X0
    beq axis
    bmi xneg
    lda LOGX,x
    ldx Y0
    bmi xpyn
    clc
    adc LOGY,x
    tax
    lda QPOS,x
    sta Z0
    rts
xpyn:
    clc
    adc LOGY,x
    tax
    lda QNEG,x
    sta Z0
    rts
xneg:
    lda LOGX,x
    ldx Y0
    bmi xnyn
    clc
    adc LOGY,x
    tax
    lda QNEG,x
    eor #$80
    sta Z0
    rts
xnyn:
    clc
    adc LOGY,x
    tax
    lda QPOS,x
    eor #$80
    sta Z0
    rts
axis:
    clc
    lda Y0
    beq axis_store
    asl
    lda #$80
    ror
axis_store:
    sta Z0
    rts

